private parts(sticker: StickerPlacement): ImagePart[] { return sticker.renderParts as unknown as ImagePart[]; }
private fixed(layout: GameLayout): FixedImage[] { return (layout.fixedLayers ?? []) as unknown as FixedImage[]; }
private byId(id: string): StickerPlacement { return this.liveLayout().stickers.find(s => s.stickerId === id)!; }
private block(id: string | null): Record<string, unknown> | undefined {
  return this.liveLayout().geoBlocks.find(block => block.blockId === id);
}

private makeNode(parent: Node, name: string, width: number, height: number): Node {
  const node = new Node(name); node.layer = Layers.Enum.UI_2D; parent.addChild(node);
  node.addComponent(UITransform).setContentSize(width, height);
  return node;
}
private destroyChildren(parent: Node): void {
  // removeAllChildren only detaches nodes; explicit destruction releases their
  // event listeners, component state and renderer references on screen resize.
  for (const child of [...parent.children]) { child.removeFromParent(); child.destroy(); }
}
private makePanel(parent: Node, name: string, width: number, height: number, color: Color, radius = 0): Node {
  const node = this.makeNode(parent, name, width, height); const g = node.addComponent(Graphics);
  g.fillColor = color;
  if (radius) g.roundRect(-width / 2, -height / 2, width, height, radius);
  else g.rect(-width / 2, -height / 2, width, height);
  g.fill(); return node;
}
private makeLabel(parent: Node, text: string, font: number, width: number, height: number,
  x = 0, y = 0, color = INK): Label {
  const node = this.makeNode(parent, 'Text', width, height); node.setPosition(x, y);
  const label = node.addComponent(Label); label.string = text; label.fontSize = font;
  label.lineHeight = font * 1.32; label.color = color; label.overflow = Label.Overflow.SHRINK;
  label.horizontalAlign = Label.HorizontalAlign.CENTER; label.verticalAlign = Label.VerticalAlign.CENTER;
  return label;
}
private makeButton(parent: Node, id: string, text: string, width: number, height: number,
  x: number, y: number, callback: () => void): Button {
  const node = this.makePanel(parent, id, width, height, new Color(231, 217, 190), 8 * this.unit);
  node.setPosition(x, y); this.makeLabel(node, text, 12 * this.unit, width - 4, height - 2);
  const button = node.addComponent(Button); button.transition = Button.Transition.NONE;
  node.on(Button.EventType.CLICK, callback, this); this.buttons.set(id, button); return button;
}
private sprite(parent: Node, frame: SpriteFrame, size: { width: number; height: number }, name: string): Node {
