    target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.CommonJS, esModuleInterop: true,
  } }).outputText;
  const localRequire = specifier => {
    if (specifier === 'cc') return cc;
    if (specifier === 'cc/env') return { PREVIEW: false, DEBUG: false };
    if (specifier.endsWith('/Oops')) return { oops };
    if (specifier.endsWith('/ResLoader')) return { resLoader };
    if (specifier.startsWith('.')) {
      return loadTs(path.relative(game, path.resolve(path.dirname(filename), `${specifier}.ts`)));
    }
    return npmRequire(specifier);
  };
  vm.runInNewContext(js, { require: localRequire, module, exports: module.exports, console }, { filename });
  return module.exports;
}

