    const textNode = this.makePanel(this.modal, 'EditableJSON', w - 24 * u, h - 162 * u, new Color(237, 229, 211), 8 * u);
    const label = this.makeLabel(textNode, '', 11 * u, w - 40 * u, h - 184 * u);
    label.horizontalAlign = Label.HorizontalAlign.LEFT; label.verticalAlign = Label.VerticalAlign.TOP; label.overflow = Label.Overflow.CLAMP;
    const placeholder = this.makeLabel(textNode, '在这里粘贴 JSON。导入只采纳位置、等比缩放、旋转、阶段、区块与层级。', 12 * u, w - 40 * u, h - 184 * u, 0, 0, MUTED);
    const box = textNode.addComponent(EditBox); box.textLabel = label; box.placeholderLabel = placeholder;
    box.inputMode = EditBox.InputMode.ANY; box.inputFlag = EditBox.InputFlag.DEFAULT; box.maxLength = -1;
    box.string = '';
