      const json = JSON.stringify(this.draft, null, 2); this.node.emit('theatre-layout-exported', json);
      if (sys.isNative) native.copyTextToClipboard(json);
      else {
        const mini = (globalThis as unknown as { wx?: { setClipboardData?: (options: { data: string }) => void } }).wx;
