        if (incoming.sceneId !== this.layout.sceneId || incoming.stickers.length !== this.layout.stickers.length) throw new Error('只能导入当前剧场的同一组完整素材');
        const result = createLayoutDraft(this.layout);
        for (const source of this.layout.stickers) {
          const item = incoming.stickers.find(sticker => sticker.stickerId === source.stickerId);
