  private saveKey(): string { return `theatre-session:${this.layout.sceneId}:${this.layout.layoutRevision}`; }
  private isKnownDraft(value: unknown): value is GameLayout {
    try { return validateTheatreDraft(value, this.sourceLayout).length === 0; } catch { return false; }
  }
  private draftKey(): string { return `theatre-layout-draft:${this.layout.sceneId}`; }
  private persist(): void { try { this.runtimeServices().setItem(this.saveKey(), JSON.stringify(this.session.exportSave())); } catch { if (this.hint) this.hint.string = '本机空间不足，进度暂未保存'; } }
  private restoreProgress(): void {
    try { const saved = this.runtimeServices().getItem(this.saveKey()); if (saved) this.session.restore(JSON.parse(saved)); }
    catch { /* Corrupt save cannot modify a new session. */ }
  }
  private onHide(): void { this.suspended = true; this.gesture = null; if (this.booted) this.persist(); }
  private onShow(): void { this.suspended = false; if (this.booted && !this.busy) this.refresh(); }

  private resourcePath(file: string): string {
    const path = file.replace(/^resources\//, '').replace(/\.png$/i, '');
    if (!path || path.startsWith('/') || path.split('/').includes('..')) throw new Error('非法本地资源路径');
    return `${this.resourcePrefix}/${path}/spriteFrame`;
  }
  private async loadFrame(file: string): Promise<SpriteFrame> {
    const cached = this.frames.get(file); if (cached) return cached;
    const source = await this.runtimeServices().loadSpriteFrame(this.resourcePath(file));
    if (!this.alive || !isValid(this.node)) throw new Error('组件已销毁');
    // Importer auto-trim changes SpriteFrame rect, not the standalone PNG pixels.
    // Keep the loader asset alive and own a full-size frame for alpha-space paper strips.
    const frame = completeSourceFrame(source, file);
    source.addRef(); this.loadedAssets.push(source);
    if (frame !== source) this.ownedFrames.add(frame);
    this.frames.set(file, frame);
    return frame;
  }
  private async loadJson(path: string): Promise<JsonAsset> {
    const asset = await this.runtimeServices().loadJson(path);
    if (!this.alive || !isValid(this.node)) throw new Error('组件已销毁');
    asset.addRef(); this.loadedAssets.push(asset); return asset;
  }
}

