export class Root extends Component {
    private static currentOwner: Root | null = null;
    private disposed = false;
    private configReady = false;
    private ownTimer: TimerManager | null = null;
    private ownAudio: AudioManager | null = null;
    private ownStorage: StorageManager | null = null;
    private ownGame: GameManager | null = null;
    private ownGui: LayerManager | null = null;
    private ownEcs: ECSRootSystem | null = null;
    /** 游戏层节点 */
    @property({
        type: Node,
        tooltip: "游戏层"
    })
    game: Node = null!;            // 可使用多摄像机自定义二维或三维游戏场景

    /** 界面层节点 */
    @property({
        type: Node,
        tooltip: "界面层"
    })
    gui: Node = null!;

    /** 框架常驻节点 */
    private persist: Node = null!

    onLoad() {
        console.log(`Oops Framework ${version}`);
        // A replacement scene owns new services; retire the previous owner before publishing them.
        Root.currentOwner?.dispose();
        Root.currentOwner = this;
        this.enabled = false;

        this.initModule();
        this.iniStart();
        this.loadConfig();
    }

    private initModule() {
        // 创建持久根节点
        this.persist = new Node("OopsFrameworkPersistNode");
        director.addPersistRootNode(this.persist);

        // Web平台查询参数管理
        oops.config.query = new GameQueryConfig();
        // 资源管理模块
        oops.res = resLoader;
        // 全局消息
        oops.message = message;
        // 创建时间模块
        this.ownTimer = this.persist.addComponent(TimerManager)!;
        oops.timer = this.ownTimer;
        // 游戏场景管理
        this.ownGame = new GameManager(this.game);
        oops.game = this.ownGame;
        // 创建游戏界面管理对象
        this.ownGui = new LayerManager();
        oops.gui = this.ownGui;
        // Upstream clear() does not empty system flows, so a scene must not re-init the old instance.
        this.ownEcs = new ECSRootSystem();
        oops.ecs = this.ownEcs;
    }

    private isCurrentOwner(): boolean {
        return !this.disposed && Root.currentOwner === this && isValid(this.node);
    }

    private loadConfig() {
        if (!this.isCurrentOwner() || this.configReady) return;
        const config_name = "config";
        resources.load(config_name, JsonAsset, (err, config) => {
            // A destroyed or superseded scene cannot overwrite its successor or retry a failed load.
            if (!this.isCurrentOwner() || this.configReady) return;
            if (err) {
                this.loadConfig();
                return;
            }
            this.configReady = true;

            oops.config.game = new GameConfig(config);

            // 本地存储模块
            this.ownStorage = new StorageManager();
            oops.storage = this.ownStorage;
            let security: IStorageSecurity = new StorageSecuritySimple();       // new StorageSecurityCrypto();
            security.key = oops.config.game.localDataKey;
            security.iv = oops.config.game.localDataIv;
            oops.storage.init(security);

            // 创建音频模块
            this.ownAudio = this.persist.addComponent(AudioManager);
            oops.audio = this.ownAudio;
            oops.audio.load();

            // 设置默认资源包
            oops.res.defaultBundleName = oops.config.game.bundleDefault;

            // 游戏界面管理
            oops.gui.mobileSafeArea = oops.config.game.mobileSafeArea;
            //@ts-ignore
            oops.gui.initLayer(this.gui, config.json.gui);

            // 初始化统计信息
            oops.config.game.stats ? profiler.showStats() : profiler.hideStats();
            // 初始化每秒传输帧数
            game.frameRate = oops.config.game.frameRate;

            this.enabled = true;
            this.init();
            this.run();

            resources.release(config_name);
        });
    }

    update(dt: number) {
        if (this.isCurrentOwner()) this.ownEcs?.execute(dt);
    }

    /** 初始化开始 */
    protected iniStart() {

    }

    /** 初始化游戏界面 */

    private init() {
        this.initGui();
        this.initEcsSystem();
        this.ownEcs!.init();

        // 游戏显示事件
        game.on(Game.EVENT_SHOW, this.onShow, this);
        // 游戏隐藏事件
        game.on(Game.EVENT_HIDE, this.onHide, this);

        // 游戏尺寸修改事件
        if (!sys.isMobile) {
            screen.on("window-resize", this.onWindowResize, this);
            screen.on("fullscreen-change", this.onFullscreenChange, this);
        }

        screen.on("orientation-change", this.onOrientationChange, this);
    }

    private onWindowResize() {
        if (this.isCurrentOwner()) oops.message.dispatchEvent(EventMessage.GAME_RESIZE);
    }

    private onFullscreenChange() {
        if (this.isCurrentOwner()) oops.message.dispatchEvent(EventMessage.GAME_FULL_SCREEN);
    }

    private onOrientationChange() {
        if (this.isCurrentOwner()) oops.message.dispatchEvent(EventMessage.GAME_ORIENTATION);
    }

    private onShow() {
        if (!this.isCurrentOwner()) return;
        this.ownTimer!.load();          // 处理回到游戏时减去逝去时间
        this.ownAudio!.resumeAll();      // 恢复所有暂停的音乐播放
        director.resume();              // 恢复暂停场景的游戏逻辑，如果当前场景没有暂停将没任何事情发生
        game.resume();                  // 恢复游戏主循环。包含：游戏逻辑，渲染，事件处理，背景音乐和所有音效
        oops.message.dispatchEvent(EventMessage.GAME_SHOW);
    }

    private onHide() {
        if (!this.isCurrentOwner()) return;
        this.ownTimer!.save();          // 处理切到后台后记录切出时间
        this.ownAudio!.pauseAll();      // 暂停所有音乐播放
        director.pause();              // 暂停正在运行的场景，该暂停只会停止游戏逻辑执行，但是不会停止渲染和 UI 响应。 如果想要更彻底得暂停游戏，包含渲染，音频和事件
        game.pause();                  // 暂停游戏主循环。包含：游戏逻辑、渲染、输入事件派发（Web 和小游戏平台除外）
        oops.message.dispatchEvent(EventMessage.GAME_HIDE);
    }

    onDestroy() {
        this.dispose();
    }

    private dispose() {
        if (this.disposed) return;
        this.disposed = true;
        this.enabled = false;
        game.off(Game.EVENT_SHOW, this.onShow, this);
        game.off(Game.EVENT_HIDE, this.onHide, this);
        screen.off("window-resize", this.onWindowResize, this);
        screen.off("fullscreen-change", this.onFullscreenChange, this);
        screen.off("orientation-change", this.onOrientationChange, this);

        // Release only this scene's services, never the newer Root's global instances.
        this.ownAudio?.music?.release();
        this.ownAudio?.effect.release();
        this.ownEcs?.clear();
        if (this.persist && isValid(this.persist)) {
            director.removePersistRootNode(this.persist);
            this.persist.destroy();
        }
        if (Root.currentOwner === this) {
            Root.currentOwner = null;
            if (oops.timer === this.ownTimer) oops.timer = null!;
            if (oops.audio === this.ownAudio) oops.audio = null!;
            if (oops.storage === this.ownStorage) oops.storage = null!;
            if (oops.game === this.ownGame) oops.game = null!;
            if (oops.gui === this.ownGui) oops.gui = null!;
            // Keep the normal static API valid between scenes without retaining old flows.
            if (oops.ecs === this.ownEcs) oops.ecs = new ECSRootSystem();
        }
    }
}

import { JsonAsset, SpriteFrame } from 'cc';
import { oops } from '../../../oops-framework/core/Oops';
import { resLoader } from '../../../oops-framework/core/common/loader/ResLoader';
import type { TheatreRuntimeServices } from '../cocos/TheatreGame';

/** Called from Root.run(), after config and StorageManager initialization. */
export function createOopsTheatreRuntime(): TheatreRuntimeServices {
  if (!oops.storage) throw new Error('Oops StorageManager 尚未初始化');
  // Old component teardown must still save through its own initialized storage service.
  const storage = oops.storage;
  return {
    async loadJson(path: string): Promise<JsonAsset> {
      const asset = await resLoader.load<JsonAsset>('resources', path, JsonAsset);
      // Upstream load() resolves null on failure, rather than rejecting.
      if (!asset) throw new Error(`剧院 JSON 加载失败：${path}`);
      return asset;
    },
    async loadSpriteFrame(path: string): Promise<SpriteFrame> {
      const frame = await resLoader.load<SpriteFrame>('resources', path, SpriteFrame);
      if (!frame) throw new Error(`剧院贴纸加载失败：${path}`);
      return frame;
    },
    getItem(key: string): string | null {
      const text = storage.get(key);
      return text === '' || text == null ? null : text;
    },
    setItem(key: string, value: string): void {
      // Keep JSON text intact; StorageManager encodes strings without double serialization.
      storage.set(key, value);
    },
  };
}
